class Solution:
    def clumsy(self, n: int) -> int:
        stack = [n]
        num = n - 1
        i = 0
        ops = ['*', '/', '+', '-']
        while num > 0:
            op = ops[i % 4]
            if op == '*':
                stack.append(stack.pop() * num)
            elif op == '/':
                x = stack.pop()
                stack.append(int(x / num))
            elif op == '+':
                stack.append(num)
            else:
                stack.append(-num)
            num -= 1
            i += 1
        return sum(stack)

