class Solution {
    public int clumsy(int n) {
        Deque<Long> st = new ArrayDeque<>();
        st.push((long) n);
        int num = n - 1, i = 0;
        char[] ops = {'*', '/', '+', '-'};
        while (num > 0) {
            char op = ops[i % 4];
            long cur = num;
            if (op == '*') {
                long x = st.pop();
                st.push(x * cur);
            } else if (op == '/') {
                long x = st.pop();
                st.push(x / cur);
            } else if (op == '+') {
                st.push(cur);
            } else {
                st.push(-cur);
            }
            num--; i++;
        }
        long res = 0;
        for (long v : st) res += v;
        return (int) res;
    }
}

