var clumsy = function(n) {
    const stack = [n];
    let num = n - 1, i = 0;
    const ops = ['*', '/', '+', '-'];
    while (num > 0) {
        const op = ops[i % 4];
        if (op === '*') {
            stack.push(stack.pop() * num);
        } else if (op === '/') {
            const x = stack.pop();
            stack.push(Math.floor(x / num));
        } else if (op === '+') {
            stack.push(num);
        } else {
            stack.push(-num);
        }
        num--; i++;
    }
    return stack.reduce((a, b) => a + b, 0);
};

